function isCheckoutMethod(method) {
    return !!(method &&
        (method.type === 'paymentlink' || method.type === 'pixcopycode') &&
        method.config &&
        method.config.provider === 'checkout');
}

function hasAnyCheckoutMethod(paymentData) {
    return !!(isCheckoutMethod(paymentData && paymentData.method1) ||
        (paymentData && paymentData.showMethod2 && isCheckoutMethod(paymentData.method2)));
}

function run (paymentMethodData, configurationData) {
                    try {
                        let paymentData;
                        try {
                            paymentData = JSON.parse(paymentMethodData);
                        } catch (e) {
                            return JSON.stringify({ status: "error", error: "Invalid paymentMethodData JSON" });
                        }

                        let configData;
                        try {
                            configData = JSON.parse(configurationData);
                        } catch (e) {
                            configData = { rawData: configurationData };
                        }

                        let checkoutConfig = null;
                        let checkoutPaymentType = null;
                        if (isCheckoutMethod(paymentData.method1)) {
                            checkoutConfig = paymentData.method1.config;
                            checkoutPaymentType = paymentData.method1.type;
                        } else if (paymentData.showMethod2 && isCheckoutMethod(paymentData.method2)) {
                            checkoutConfig = paymentData.method2.config;
                            checkoutPaymentType = paymentData.method2.type;
                        }

                        if (!checkoutConfig) {
                            return {step: 'noCheckout'};
                        }

                        // Verificar TODOS os métodos checkout para determinar quais tipos de pagamento gerar.
                        // Quando method1=paymentlink+checkout e method2=pixcopycode+checkout, o checkoutPaymentType
                        // seria 'paymentlink' (null no paymentMethodsToGenerate), fazendo a API não gerar PIX.
                        var needsPix = checkoutPaymentType === 'pixcopycode';
                        if (!needsPix && paymentData.showMethod2 && paymentData.method2 && paymentData.method2.type === 'pixcopycode' && paymentData.method2.config && paymentData.method2.config.provider === 'checkout') {
                            needsPix = true;
                        }
                        var paymentMethodsToGenerate = needsPix ? ['Pix'] : null;

                        let products = [];

                        if (configData.items && Array.isArray(configData.items)) {
                            products = configData.items.map(item => ({
                                description: item.name || item.retailer_id || "Produto",
                                price: String((item.amount.value || 0)),
                                quantity: item.quantity || 1
                            }));
                        } else {
                            const itemsMatch = configurationData && configurationData.match(/"items"\s*:\s*"\[(.+?)\]"/s);

                            if (itemsMatch) {
                                let itemsStr = itemsMatch[1];
                                itemsStr = itemsStr.replace(/\\"/g, '"').replace(/\"/g, '"');
                                const objectRegex = /\{[^{}]*\{[^{}]*\}[^{}]*\}/g;
                                const matches = itemsStr.match(objectRegex);

                                if (matches) {
                                    for (let i = 0; i < matches.length; i++) {
                                        const part = matches[i].trim();
                                        const nameMatch = part.match(/"name"\s*:\s*"([^"]+)"/);
                                        const valueMatch = part.match(/"value"\s*:\s*(\d+(?:\.\d+)?)/);
                                        const quantityMatch = part.match(/"quantity"\s*:\s*(\d+)/);

                                        if (nameMatch && valueMatch && quantityMatch) {
                                            products.push({
                                                description: nameMatch[1],
                                                price: String(parseFloat(valueMatch[1])),
                                                quantity: parseInt(quantityMatch[1])
                                            });
                                        }
                                    }
                                }
                            }
                        }

                        const checkoutRequest = {
                            step: "link",
                            merchantId: checkoutConfig.merchantId,
                            botShortName: "{{application.shortName}}" || checkoutConfig.source,
                            customer: {
                                ...checkoutConfig.customer,
                                identity: "{{contact.identity}}"
                            },
                            products: products,
                            currency: checkoutConfig.currency || 'BRL',
                            channel: checkoutConfig.channel || 'WhatsApp',
                            source: checkoutConfig.source || 'bot',
                            paymentMethodsToGenerate: paymentMethodsToGenerate,
                            paymentReturn: checkoutConfig.paymentReturn
                        };

                        return JSON.stringify(checkoutRequest);

                    } catch (error) {
                        return JSON.stringify({ status: "error", error: error.message });
                    }
                }

