function run(checkoutRequest, paymentMethodData, paymentStatusFeedbackTime) {
                if (!checkoutRequest) {
                    return 0;
                }

                try {
                    checkoutRequest = JSON.parse(checkoutRequest);
                    paymentMethodData = JSON.parse(paymentMethodData);
                } catch (e) {
                    return 0;
                }

                if (!hasAnyCheckoutMethod(paymentMethodData)) {
                    return 0;
                }

                const method1HasFeedback = isCheckoutMethod(paymentMethodData.method1) &&
                    paymentMethodData.method1.config &&
                    paymentMethodData.method1.config.paymentReturn &&
                    paymentMethodData.method1.config.paymentReturn.feedbackReturnPayment === true;
                const method2HasFeedback = paymentMethodData.showMethod2 &&
                    isCheckoutMethod(paymentMethodData.method2) &&
                    paymentMethodData.method2.config &&
                    paymentMethodData.method2.config.paymentReturn &&
                    paymentMethodData.method2.config.paymentReturn.feedbackReturnPayment === true;

                if (!method1HasFeedback && !method2HasFeedback) {
                    return 0;
                }

                // Preservar timer existente (cenário de loopback enquanto aguarda pagamento)
                paymentStatusFeedbackTime = Number(paymentStatusFeedbackTime);
                if (paymentStatusFeedbackTime && paymentStatusFeedbackTime > 0) {
                    return paymentStatusFeedbackTime;
                }

                if (
                    checkoutRequest.paymentReturn &&
                    checkoutRequest.paymentReturn.paymentStatusFeedbackTime != null
                ) {
                    return Number(checkoutRequest.paymentReturn.paymentStatusFeedbackTime);
                }

                return 1;
            }

