function getHeaders(token) {
    return {
        Authorization: `Bearer ${token}`
    };
}

async function execFetch(url, options) {
    try {
        const response = await request.fetchAsync(url, options);

        let parsedBody;
        try {
            parsedBody = await response.jsonAsync();
        } catch (e) {
            parsedBody = await response; 
        }

        return {
             status: response.status,
             body: parsedBody
        }
    } catch (error) {
        throw error;
    }
}

async function getToken(checkoutRequest, urlBase, secret) {
    const bodyRequest = {
        botShortName: checkoutRequest.botShortName,
        secret: secret
    };

    let response = await execFetch(`${urlBase}/bot`, {
            method: 'POST',
            body: bodyRequest
        });

    return {
        status: response.status,
        body: response.body && response.body.token ? response.body.token : response.body
    }
}

async function getPaymentResponse(checkoutId, token, urlBase) {    
    try {
        var response = await execFetch(`${urlBase}/V0.1/payment?id=${checkoutId}`, { 
            method: 'GET', 
            headers: getHeaders(token)       
        });  

        return {
            status: response.status,
            body: response.body
        }
    } catch (error) {
        throw error;
    }
}


            async function getCheckoutLink(token, checkoutRequest, urlBase) {
                const bodyRequest = {
                    customer: checkoutRequest.customer,
                    products: checkoutRequest.products,
                    currency: checkoutRequest.currency,
                    channel: checkoutRequest.channel,
                    source: checkoutRequest.source,
                    paymentMethodsToGenerate: checkoutRequest.paymentMethodsToGenerate || null
                };

            let response = await execFetch(
                urlBase + "/v0.1/checkout/purchase?merchant-id=" + checkoutRequest.merchantId,
                {
                    method: 'POST',
                    headers: getHeaders(token),
                    body: bodyRequest
                }
            );

            // 🔴 Erro
            if (Number(response.status) !== 200) {
                return {
                    success: false,
                    status: response.status,
                    bodyRequest,
                    error: response || "Unknown error from checkout API"
                };
            }

            // ✅ Sucesso
            // Tentar extrair o código PIX de diferentes possíveis caminhos na resposta da API
            var pixQrCode = (response.body.pix && response.body.pix.qrCodeText)
                || response.body.pixQrCodeText
                || response.body.pixCode
                || (response.body.pix && response.body.pix.copyAndPaste)
                || null;

            return {
                success: true,
                status: response.status,
                bodyRequest,
                link: response.body.link,
                purchaseId: response.body.purchaseId,
                pixQrCodeText: pixQrCode,
                pixKey: (response.body.pix && response.body.pix.pixKey) || null,
                pixName: (response.body.pix && response.body.pix.merchantName) || null,
                rawBody: response.body
            };
}

async function run(checkoutRequest, checkoutConfig, checkoutSecretCommandResponse) {
    try {
        const config = typeof checkoutConfig === 'string' ? JSON.parse(checkoutConfig) : checkoutConfig;
        const URL_BASE = config.baseUrl;
        const URL_BASE_AUTH = config.authUrl;
        const secretResponse = typeof checkoutSecretCommandResponse === 'string' ? JSON.parse(checkoutSecretCommandResponse) : checkoutSecretCommandResponse;
        const SECRET = secretResponse && secretResponse.resource ? secretResponse.resource : null;
        if (!SECRET) throw new Error('Falha ao ler bucket checkout-secret: Bucket "checkout-secret" não encontrado ou vazio');

        checkoutRequest = JSON.parse(checkoutRequest);
        let urlBase = URL_BASE;
        let urlAuthBase = URL_BASE_AUTH;

        let responseToken = await getToken(checkoutRequest, urlAuthBase, SECRET);              
        if(Number(responseToken.status) !== 200) {
            responseToken = await getToken(checkoutRequest, urlAuthBase, SECRET);
        }    

        if (Number(responseToken.status) !== 200) {
            return JSON.stringify({
                status: "error",
                api: "getToken",
                httpStatus: responseToken.status,
                message: "Erro ao gerar token do checkout",
                details: responseToken.body
            });
        }     

        let  checkoutLink = await getCheckoutLink(responseToken.body,  checkoutRequest, urlBase);         
        if(Number(checkoutLink.status) !== 200) {
            checkoutLink = await getCheckoutLink(responseToken.body,  checkoutRequest, urlBase);   
        }
      if (!checkoutLink.success) {
        return JSON.stringify({
            status: "error",
            api: "getCheckoutLink",
            httpStatus: checkoutLink.status,
            message: "Erro ao gerar link do checkout",
            bodyRequest: checkoutLink.bodyRequest,
            details: checkoutLink.error,
            responseToken
        });
    }

        return JSON.stringify({
            apiTokenStatus:  responseToken ? responseToken.status : 500,
            apiTokenResponse: responseToken ? responseToken : {},
            apiLinkStatus:  checkoutLink ? checkoutLink.status : 500,
            apiLinkResponse: checkoutLink ? checkoutLink : {},
            apiLinkRequest: checkoutLink ? checkoutLink.bodyRequest : {},            
            link: checkoutLink.link,
            purchaseId: checkoutLink.purchaseId,
            checkoutId: checkoutLink.purchaseId || getIdCheckoutId(checkoutLink.link),
            pixQrCodeText: checkoutLink.pixQrCodeText || null,
            pixKey: checkoutLink.pixKey || null,
            pixName: checkoutLink.pixName || null,
            rawApiResponse: checkoutLink.rawBody || null,
            botToken: responseToken ? responseToken.body : null,
            status: "created",            
        });

    } catch (error) {
        return JSON.stringify({           
            status: "error",
            error: error.message
        });
    }
}

function getIdCheckoutId(url) {
    if (!url || typeof url !== "string") return null;
    const idParam = url.split("id=")[1];
    if (!idParam) return null;

    const id = idParam.split("&")[0];
    return id;
}

function getFrontEndToken(url) {
  const tokenParam = url.split("token=")[1];
  if (!tokenParam) return null;

  return tokenParam.split("&")[0];
