async function run(checkoutResponse, checkoutRequest, inputCheckout, checkoutConfig, checkoutSecretCommandResponse, paymentMethodData) {

    let response =  { hasSavedCard: false };
    const regexOutraForma = /outra\s+forma/i;
    if (typeof inputCheckout === "string" && regexOutraForma.test(inputCheckout)) {
        return JSON.stringify(response);
    }

    try {
        const paymentData = typeof paymentMethodData === 'string' ? JSON.parse(paymentMethodData) : paymentMethodData;
        const hasPaymentLink =
            (paymentData && paymentData.method1 && paymentData.method1.type === 'paymentlink') ||
            (paymentData && paymentData.showMethod2 && paymentData.method2 && paymentData.method2.type === 'paymentlink');
        if (!hasPaymentLink) return JSON.stringify(response);
    } catch (e) { return JSON.stringify(response); }

     try {        
        const config = typeof checkoutConfig === 'string' ? JSON.parse(checkoutConfig) : checkoutConfig;
        const URL_BASE = config.baseUrl;
        const URL_BASE_AUTH = config.authUrl;
        const secretResponse = typeof checkoutSecretCommandResponse === 'string' ? JSON.parse(checkoutSecretCommandResponse) : checkoutSecretCommandResponse;
        const SECRET = secretResponse && secretResponse.resource ? secretResponse.resource : null;
        if (!SECRET) throw new Error('Falha ao ler bucket checkout-secret: Bucket "checkout-secret" não encontrado ou vazio');

        const checkoutData = typeof checkoutResponse === 'string' ? JSON.parse(checkoutResponse) : checkoutResponse;
        const requestData = typeof checkoutRequest === 'string' ? JSON.parse(checkoutRequest) : checkoutRequest;        

        let urlBase = URL_BASE;
        let urlAuthBase = URL_BASE_AUTH;

        try {
            if(requestData && requestData.step !== 'link')  {
                return response;
            }

            let responseCards = await getCustomerCards(checkoutData.checkoutId, checkoutData.botToken, urlBase);

            if (Number(responseCards.status) === 401) {
                const responseToken = await getToken(requestData, urlAuthBase, SECRET);
                if (Number(responseToken.status) === 200) {
                    responseCards = await getCustomerCards(checkoutData.checkoutId, responseToken.body, urlBase);
                }
            }

            if (Number(responseCards.status) === 200 && responseCards.body) {
                const savedCard = responseCards.body;

                response = {
                    hasSavedCard: true,
                    card: {
                        id: savedCard.id,
                        lastFourDigits: savedCard.lastFourDigits

                    }
                };
            }

        } catch (apiError) {      
            response = {
                    hasSavedCard: false,
                    status: 'error', 
                    message: 'Erro no request da API: ' + apiError.message                    
                };
        } 
    return JSON.stringify(response);

    } catch (error) {
        return JSON.stringify({ hasSavedCard: false, status: 'error', message: 'Erro ao configurar feedback: ' + error.message });
    }
}

