function run(paymentMethodData, customerCardsResponse, checkoutRequest) {
    try {
        // Se não há dados do método de pagamento, não aguarda input
        if (!paymentMethodData) {
            return "false";
        }       

        const customerCards =  typeof customerCardsResponse === 'string' ? JSON.parse(customerCardsResponse) : null;
        const paymentData = typeof paymentMethodData === 'string' ? JSON.parse(paymentMethodData) : paymentMethodData;
        checkoutRequest = JSON.parse(checkoutRequest);        

        if(customerCards && !customerCards.hasSavedCard && checkoutRequest.step === 'link' && !hasTwoCheckoutMethods) {
            return false;
        }

        // Verificar se existe checkout e feedback habilitado
        const hasCheckout = hasAnyCheckoutMethod(paymentData);
        let feedbackEnabled = false;

        if (isCheckoutMethod(paymentData.method1) &&
            paymentData.method1.config &&
            paymentData.method1.config.paymentReturn &&
            paymentData.method1.config.paymentReturn.feedbackReturnPayment === true) {
            feedbackEnabled = true;
        }

        if (!feedbackEnabled && paymentData.showMethod2 &&
            isCheckoutMethod(paymentData.method2) &&
            paymentData.method2.config &&
            paymentData.method2.config.paymentReturn &&
            paymentData.method2.config.paymentReturn.feedbackReturnPayment === true) {
            feedbackEnabled = true;
        }

        // Aguarda input quando tem checkout configurado (independente do feedback)
        // Isso é necessário para capturar cliques de botões de pagamento com 1 clique
        const shouldWaitForInput = hasCheckout;
        return shouldWaitForInput ? "true" : "false";

    } catch (error) {
        // Em caso de erro, não aguarda input para não travar o fluxo
        return "false";
    }
}

function run(checkoutRequest, customerCardsResponse) {
    try {
        const card = typeof customerCardsResponse === "string"
            ? JSON.parse(customerCardsResponse).card
            : customerCardsResponse.card;

        const order = typeof checkoutRequest === "string"
            ? JSON.parse(checkoutRequest)
            : checkoutRequest;        

        // =========================
        // CARTÃO
        // =========================        
        const last4 = card.lastFourDigits;
        const id = card.id;

        // =========================
        // RESUMO DO PEDIDO
        // =========================
        let resumo = `🛒 Resumo do seu pedido\n\n`;
        let totalGeral = 0;

        order.products.forEach((product, index) => {
            const nome = product.description || "Produto";
            const quantidade = Number(product.quantity) || 1;
            const precoUnitario = parseFloat(product.price || 0);
            const subtotal = quantidade * precoUnitario;

            totalGeral += subtotal;

            const precoFormatado = precoUnitario.toFixed(2).replace('.', ',');
            const subtotalFormatado = subtotal.toFixed(2).replace('.', ',');

            resumo += `*${nome}*
`;
            resumo += `${quantidade} x R$ ${precoFormatado} = R$ ${subtotalFormatado}\n`;           

            if (index < order.products.length - 1) {
                resumo += `------------------------\n`;
            }

            resumo += `\n`;
        });

        const totalFormatado = totalGeral.toFixed(2).replace('.', ',');


        resumo += `-------------------------------\n`;
        resumo += `*Valor total: R$ ${totalFormatado}*\n`;
        resumo += `-------------------------------\n\n`;
        resumo += `Como deseja pagar?\n\n`;      

        // =========================
        // CTA WHATSAPP
        // =========================
        return JSON.stringify({
            type: "interactive",
            interactive: {
                type: "button",
                body: {
                    text: `${resumo}`
                },                
                action: {
                    buttons: [
                        {
                            type: "reply",
                            reply: {
                                id: `PAY_ONE_CLICK_${id}`,
                                title: `Cartão final ${last4}`
                            }
                        },
                        {
                            type: "reply",
                            reply: {
                                id: "ACCESS_PAYMENT_LINK",
                                title: "Outra forma"
                            }
                        }
                    ]
                }
            }
        });

    } catch (error) {
        return JSON.stringify({
            type: "text",
            text: "❌ Ocorreu um erro ao processar o pagamento."
        });
    }
}
